5|import { displayTitle } from "@/core/music-credit";
6|import { effectiveEnd, gainVolume } from "@/core/music-playback";
7|import type { MusicMode, MusicModeId, Track } from "@/core/music";
8|import { MusicStyleControl } from "./folio/music-style-control";
9|import { RainAmbience } from "./rain-button";
